#include <bits/stdc++.h>
using namespace std;

struct CostFlow {
    struct Edge {
        int to, rev, cap, cost;
    };

    int N, S, T;
    vector<vector<Edge>> g;
    vector<int> h;

    CostFlow(int n, int s, int t) : N(n), S(s), T(t), g(n) {}

    int add_edge(int v, int u, int cap, int cost) {
        Edge a{u, (int)g[u].size(), cap, cost};
        Edge b{v, (int)g[v].size(), 0, -cost};
        g[v].push_back(a);
        g[u].push_back(b);
        return (int)g[v].size() - 1;
    }

    void init_potential() {
        const int INF = INT_MAX / 2;
        vector<int> dist(N, INF);
        dist[S] = 0;

        for (int it = 0; it < N - 1; ++it) {
            bool changed = false;
            for (int v = 0; v < N; ++v) {
                if (dist[v] == INF) continue;
                for (const Edge &e : g[v]) {
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                        dist[e.to] = dist[v] + e.cost;
                        changed = true;
                    }
                }
            }
            if (!changed) break;
        }

        h.assign(N, 0);
        for (int i = 0; i < N; ++i)
            if (dist[i] < INF) h[i] = dist[i];
    }

    pair<int,int> run() {
        init_potential();

        int flow = 0, total_cost = 0;
        const int INF = INT_MAX / 2;

        while (true) {
            vector<int> dist(N, INF), prev_v(N, -1), prev_e(N, -1), max_f(N, 0);
            priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;

            dist[S] = 0;
            max_f[S] = INT_MAX;
            pq.push({0, S});

            while (!pq.empty()) {
                int d = pq.top().first;
                int v = pq.top().second;
                pq.pop();
                if (d != dist[v]) continue;

                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap <= 0) continue;

                    int rcost = e.cost + h[v] - h[e.to];
                    int nd = d + rcost;

                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        prev_v[e.to] = v;
                        prev_e[e.to] = i;
                        max_f[e.to] = min(max_f[v], e.cap);
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[T] == INF) break;

            int add = max_f[T];
            for (int v = T; v != S; v = prev_v[v]) {
                Edge &e = g[prev_v[v]][prev_e[v]];
                total_cost += add * e.cost;
                e.cap -= add;
                g[v][e.rev].cap += add;
            }

            flow += add;

            for (int v = 0; v < N; ++v)
                if (dist[v] < INF) h[v] += dist[v];
        }

        return make_pair(flow, total_cost);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, K, c, d;
    cin >> n >> m >> K >> c >> d;

    const int max_time = 120;
    vector<int> start(K);
    for (int i = 0; i < K; ++i) cin >> start[i];

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    auto id = [n](int t, int j) {
        return t * n + (j - 1);
    };

    int S = max_time * n;
    int T = S + 1;
    CostFlow mf(max_time * n + 2, S, T);

    for (int i = 0; i < K; ++i)
        mf.add_edge(S, id(0, start[i]), 1, 0);

    for (int t = 0; t < max_time; ++t)
        mf.add_edge(id(t, 1), T, K, c * t);

    for (int t = 0; t < max_time - 1; ++t) {
        for (int j = 1; j <= n; ++j) {
            for (int nb : adj[j]) {
                for (int z = 0; z <= 52; ++z)
                    mf.add_edge(id(t, j), id(t + 1, nb), 1, d * (2 * z + 1));
            }
            mf.add_edge(id(t, j), id(t + 1, j), K, 0);
        }
    }

    pair<int,int> ans = mf.run();
    cout << ans.second << '\n';

    return 0;
}
