import java.io.*;
import java.util.*;

public class Main {
    static class CostFlow {
        static class Edge {
            int to, rev, cap, cost;
            Edge(int to, int rev, int cap, int cost) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
                this.cost = cost;
            }
        }

        int N, S, T;
        List<List<Edge>> g;
        int[] h;

        CostFlow(int n, int s, int t) {
            N = n;
            S = s;
            T = t;
            g = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                g.add(new ArrayList<>());
            }
        }

        int addEdge(int v, int u, int cap, int cost) {
            Edge a = new Edge(u, g.get(u).size(), cap, cost);
            Edge b = new Edge(v, g.get(v).size(), 0, -cost);
            g.get(v).add(a);
            g.get(u).add(b);
            return g.get(v).size() - 1;
        }

        void initPotential() {
            final int INF = Integer.MAX_VALUE / 2;
            int[] dist = new int[N];
            Arrays.fill(dist, INF);
            dist[S] = 0;

            for (int it = 0; it < N - 1; it++) {
                boolean changed = false;
                for (int v = 0; v < N; v++) {
                    if (dist[v] == INF) continue;
                    for (Edge e : g.get(v)) {
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                            dist[e.to] = dist[v] + e.cost;
                            changed = true;
                        }
                    }
                }
                if (!changed) break;
            }

            h = new int[N];
            for (int i = 0; i < N; i++) {
                if (dist[i] < INF) h[i] = dist[i];
            }
        }

        int[] run() {
            initPotential();

            int flow = 0, totalCost = 0;
            final int INF = Integer.MAX_VALUE / 2;

            while (true) {
                int[] dist = new int[N];
                int[] prevV = new int[N];
                int[] prevE = new int[N];
                int[] maxF = new int[N];
                Arrays.fill(dist, INF);
                Arrays.fill(prevV, -1);
                Arrays.fill(prevE, -1);

                dist[S] = 0;
                maxF[S] = Integer.MAX_VALUE;
                PriorityQueue<Pair> pq = new PriorityQueue<>();
                pq.offer(new Pair(0, S));

                while (!pq.isEmpty()) {
                    Pair cur = pq.poll();
                    int d = cur.dist;
                    int v = cur.vertex;
                    if (d != dist[v]) continue;

                    for (int i = 0; i < g.get(v).size(); i++) {
                        Edge e = g.get(v).get(i);
                        if (e.cap <= 0) continue;

                        int rcost = e.cost + h[v] - h[e.to];
                        int nd = d + rcost;

                        if (nd < dist[e.to]) {
                            dist[e.to] = nd;
                            prevV[e.to] = v;
                            prevE[e.to] = i;
                            maxF[e.to] = Math.min(maxF[v], e.cap);
                            pq.offer(new Pair(nd, e.to));
                        }
                    }
                }

                if (dist[T] == INF) break;

                int add = maxF[T];
                for (int v = T; v != S; v = prevV[v]) {
                    Edge e = g.get(prevV[v]).get(prevE[v]);
                    totalCost += add * e.cost;
                    e.cap -= add;
                    g.get(v).get(e.rev).cap += add;
                }

                flow += add;

                for (int v = 0; v < N; v++) {
                    if (dist[v] < INF) h[v] += dist[v];
                }
            }

            return new int[]{flow, totalCost};
        }

        static class Pair implements Comparable<Pair> {
            int dist, vertex;
            Pair(int d, int v) {
                dist = d;
                vertex = v;
            }
            public int compareTo(Pair other) {
                return Integer.compare(this.dist, other.dist);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        final int maxTime = 120;
        int[] start = new int[K];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < K; i++) {
            start[i] = Integer.parseInt(st.nextToken());
        }

        List<List<Integer>> adj = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            adj.get(x).add(y);
            adj.get(y).add(x);
        }

        // id function: t * n + (j-1)
        int S = maxTime * n;
        int T = S + 1;
        CostFlow mf = new CostFlow(maxTime * n + 2, S, T);

        for (int i = 0; i < K; i++) {
            mf.addEdge(S, 0 * n + (start[i] - 1), 1, 0);
        }

        for (int t = 0; t < maxTime; t++) {
            mf.addEdge(t * n + (1 - 1), T, K, c * t);
        }

        for (int t = 0; t < maxTime - 1; t++) {
            for (int j = 1; j <= n; j++) {
                int u = t * n + (j - 1);
                // stay
                mf.addEdge(u, (t + 1) * n + (j - 1), K, 0);
                for (int nb : adj.get(j)) {
                    int v = (t + 1) * n + (nb - 1);
                    for (int z = 0; z <= 52; z++) {
                        mf.addEdge(u, v, 1, d * (2 * z + 1));
                    }
                }
            }
        }

        int[] ans = mf.run();
        pw.println(ans[1]);
        pw.flush();
        pw.close();
        br.close();
    }
}
